class Solution:
    def wateringPlants(self, plants: List[int], capacity: int) -> int:
        steps = 0
        water = capacity
        for i, need in enumerate(plants):
            if water < need:
                steps += i + (i + 1)
                water = capacity
            else:
                steps += 1
            water -= need
        return steps

