from bisect import bisect_right

class Solution:
    def wateringPlants(self, plants: List[int], capacity: int) -> int:
        n = len(plants)
        pre = [0] * (n + 1)
        for i, p in enumerate(plants):
            pre[i + 1] = pre[i] + p

        steps, j = 0, 0
        while j < n:
            k = bisect_right(pre, pre[j] + capacity) - 2
            if k >= n - 1:
                steps += n
                break
            steps += 2 * (k + 1)
            j = k + 1
        return steps

