class Solution {
public:
    int wateringPlants(vector<int>& plants, int capacity) {
        int n = plants.size();
        vector<long long> pre(n + 1, 0);
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + plants[i];

        int steps = 0, j = 0;
        while (j < n) {
            int lo = j + 1, hi = n, found = j;
            while (lo <= hi) {
                int mid = lo + (hi - lo) / 2;
                if (pre[mid] - pre[j] <= capacity) { found = mid; lo = mid + 1; }
                else hi = mid - 1;
            }
            int k = found - 1;
            if (k >= n - 1) { steps += n; break; }
            steps += 2 * (k + 1);
            j = k + 1;
        }
        return steps;
    }
};

